	void OrdlidarDriver::Disconnect()
	{
		rx_thread_exit_flag_ = true;
		if (serial_)
		{
			if (serial_->isOpen())
			{
				serial_->closePort();
			}
		}

		if ((rx_thread_ != nullptr) && rx_thread_->joinable())
		{
			rx_thread_->join();
			delete rx_thread_;
			rx_thread_ = NULL;
		}

		ResetFullScanReady();
		ResetOneScanReady();

		is_connected_ = false;
	}

