bool Serial::SerialImpl::setBreak(bool level) {
  if (is_open_ == false) {
    return false;
  }

  if (level) {
    //EscapeCommFunction (fd_, SETBREAK);
    //::SetCommBreak(fd_);
    if (::SetCommBreak(fd_) == FALSE) {
      return false;
    }
  } else {
    //::ClearCommBreak(fd_);
    //EscapeCommFunction (fd_, CLRBREAK);
    if (::ClearCommBreak(fd_) == FALSE) {
      return false;
    }
  }

  return true;
