Serial::SerialImpl::SerialImpl(const string &port, unsigned long baudrate,
                               bytesize_t bytesize,
                               parity_t parity, stopbits_t stopbits,
                               flowcontrol_t flowcontrol)
  : port_(port), fd_(-1), pid(-1), is_open_(false), xonxoff_(false),
    rtscts_(false), timeout_(Timeout()), baudrate_(baudrate), byte_time_ns_(0),
    parity_(parity), bytesize_(bytesize), stopbits_(stopbits),
    flowcontrol_(flowcontrol) {
  pthread_mutex_init(&this->read_mutex, NULL);
  pthread_mutex_init(&this->write_mutex, NULL);

}

Serial::SerialImpl::~SerialImpl() {
  close();
  pthread_mutex_destroy(&this->read_mutex);
  pthread_mutex_destroy(&this->write_mutex);
}

bool Serial::SerialImpl::open() {
  if (port_.empty()) {
    return false;
  }

  if (isOpen()) {
    return true;
  }

  pid = -1;
#ifdef USE_LOCK_FILE
  pid = getpid();

  if (LOCK(port_.c_str(), pid)) {
    fprintf(stderr, "Could not lock serial port for exclusive access\n");
    return false;
  }

#endif

  fd_ = ::open(port_.c_str(),
               O_RDWR | O_NOCTTY | O_NONBLOCK | O_APPEND | O_NDELAY);

  if (fd_ == -1) {
    switch (errno) {
      case EINTR:
        // Recurse because this is a recoverable error.
        return open();

      case EIO:

//        fprintf(stderr, "I/O error\n");

      case ENFILE:

//        fprintf(stderr, "File table overflow\n");

      case EMFILE:

//        fprintf(stderr, "Too many open files\n");

      default:
//        fprintf(stderr, "Default: %d\n", errno);
        close();
        return false;
    }
  }

  termios tio;

  if (!getTermios(&tio)) {
    close();
    return false;
  }

  set_common_props(&tio);
  set_databits(&tio, bytesize_);
  set_parity(&tio, parity_);
  set_stopbits(&tio, stopbits_);
  set_flowcontrol(&tio, flowcontrol_);

  if (!setTermios(&tio)) {
    close();
    return false;
  }

  if (!setBaudrate(baudrate_)) {
    close();
    return false;
  }

  // Update byte_time_ based on the new settings.
  uint32_t bit_time_ns = 1e9 / baudrate_;
  byte_time_ns_ = bit_time_ns * (1 + bytesize_ + parity_ + stopbits_);

  // Compensate for the stopbits_one_point_five enum being equal to int 3,
  // and not 1.5.
  if (stopbits_ == stopbits_one_point_five) {
    byte_time_ns_ += ((1.5 - stopbits_one_point_five) * bit_time_ns);
  }

  is_open_ = true;
  return true;
}

Serial::SerialPortError Serial::SerialImpl::getSystemError(
  int systemErrorCode) const {
  if (systemErrorCode == -1) {
    systemErrorCode = errno;
  }

  Serial::SerialPortError error;

  switch (systemErrorCode) {
    case ENODEV:
      error = Serial::DeviceNotFoundError;
      break;
#ifdef ENOENT

    case ENOENT:
      error = Serial::DeviceNotFoundError;
      break;
#endif

    case EACCES:
      error = Serial::PermissionError;
      break;

    case EBUSY:
      error = Serial::PermissionError;
      break;

    case EAGAIN:
      error = Serial::ResourceError;
      break;

    case EIO:
      error = Serial::ResourceError;
      break;

    case EBADF:
      error = Serial::ResourceError;
      break;
#ifdef __MACH__

    case ENXIO:
      error = Serial::ResourceError;
      break;
#endif
#ifdef EINVAL

    case EINVAL:
      error = Serial::UnsupportedOperationError;
      break;
#endif
#ifdef ENOIOCTLCMD

    case ENOIOCTLCMD:
      error = Serial::UnsupportedOperationError;
      break;
#endif
#ifdef ENOTTY

    case ENOTTY:
      error = Serial::UnsupportedOperationError;
      break;
#endif
#ifdef EPERM

    case EPERM:
      error = Serial::PermissionError;
      break;
#endif

    default:
      error = Serial::UnknownError;
      break;
  }

  return error;
}

void Serial::SerialImpl::close() {
  if (isOpen()) {
    is_open_ = false;
  }

  if (fd_ != -1) {
    ::close(fd_);
  }

#ifdef USE_LOCK_FILE

  if (pid != -1) {
    UNLOCK(port_.c_str(), pid);
  }

  pid = -1;
#endif
  fd_ = -1;

}

