            self.move_x(step)
        elif direction in ['y', 'Y']:
            self.move_y(step)
        else:
            print("ERROR!Invalid direction!")

    def move_x(self, step):
        ORDER["VX"][1] = conver2u8(step, PARAM["VX_LIMIT"])
