        ORDER["MOVE_MODE"][1] = value
        self.__send("MOVE_MODE")

    def gait_type(self, mode):
        """
        改变机器狗的步态
        Change the gait of the robot
        """
        if mode == "trot":
            value = 0x00
        elif mode == "walk":
            value = 0x01
        elif mode == "high_walk":
            value = 0x02
        ORDER["GAIT_TYPE"][1] = value
        self.__send("GAIT_TYPE")

