double getContourAreaMax(std::vector<std::vector<cv::Point>> contours, uint *index)
{
    double area_max = 0;
    // Loop over all closed contours
    for (uint i = 0; i < contours.size(); i++)
    {
        double area = cv::contourArea(contours[i]);
        if (area > area_max)
        {
            area_max = area;
            *index = i;
        }
    }
    return area_max;
}

